import { describe, expect, it } from 'vitest';

import dataset from '../data/pharmacies-ticino.json';
import { validatePharmacyList } from '../services/pharmacies/types';

/**
 * Schema guard for `data/pharmacies-ticino.json` (#6400, first item of the
 * #6173 pharmacy-portal MVP), generated by
 * `scripts/import-pharmacies-ticino.mjs` from the #6398-verified ofct.ch
 * anagraphic table across the 4 covered regions (Locarnese excluded).
 */
describe('pharmacies-ticino dataset', () => {
  it('passes the Pharmacy schema guard with zero errors', () => {
    expect(validatePharmacyList(dataset.pharmacies)).toEqual([]);
  });

  it('has a non-trivial pharmacy count', () => {
    expect(dataset.pharmacies.length).toBeGreaterThan(50);
  });

  it('every pharmacy is Ticino/CH sourced from ofct.ch', () => {
    for (const p of dataset.pharmacies) {
      expect(p.canton).toBe('Ticino');
      expect(p.country).toBe('CH');
      expect(p.sourceUrl).toMatch(/^https:\/\/www\.ofct\.ch\//);
      expect(p.sourceType).toBe('official');
    }
  });

  it('has no duplicate ids', () => {
    const ids = dataset.pharmacies.map((p) => p.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('keeps the pharmacy-list consumer compatible with observability metadata', () => {
    const observableEnvelope = {
      ...dataset,
      _warnings: ['luganese: skipped 1/20 malformed row(s)'],
      _skippedMalformedRows: 1,
    };

    expect(validatePharmacyList(observableEnvelope.pharmacies)).toEqual([]);
    expect(observableEnvelope.pharmacies).toHaveLength(dataset.pharmacies.length);
  });
});
